#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);
import {createChatOrchestrator} from './chatOrchestrator.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {
  answering,
  failing,
  recordingSessionStore,
  writeSignalPromptBuilder,
} from '../infrastructure/writeSignalTestSupport.js';
import {captureErrors} from '../shared/logCaptureTestSupport.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

const sessionWith = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content, timestamp: SENT_AT}],
});

describe('the session write signal', () => {
  const errors = captureErrors();

  // One outcome value per turn, so each test below can assert with a single expect.
  const turn = async (sessionStore: SessionStore, provider: AIProvider = answering('hi')): Promise<string> => {
    const orchestrator = createChatOrchestrator(provider, writeSignalPromptBuilder, undefined, {sessionStore});
    return orchestrator.processMessage(sessionWith('hello')).catch((error: Error) => `threw: ${error.message}`);
  };

  it('saves once for one processed user message', async () => {
    const saved: string[] = [];

    await turn(recordingSessionStore(session => void saved.push(session.sessionId)));

    expect(saved).toEqual(['s1']);
  });

  it('saves once and still rethrows when the provider fails', async () => {
    const saved: string[] = [];
    const store = recordingSessionStore(session => void saved.push(session.sessionId));

    const outcome = await turn(store, failing('provider gone'));

    expect({outcome, saved}).toEqual({outcome: 'threw: provider gone', saved: ['s1']});
  });

  it('keeps the turn alive and logs once when save rejects', async () => {
    const outcome = await turn(recordingSessionStore(() => Promise.reject(new Error('mongo down'))));

    expect({outcome, errors}).toEqual({
      outcome: 'hi',
      errors: [{category: 'orchestrator', message: 'session save failed', sessionId: 's1', error: 'mongo down'}],
    });
  });

  it('keeps the turn alive when save throws synchronously', async () => {
    const outcome = await turn(
      recordingSessionStore(() => {
        throw new Error('forgot to be async');
      })
    );

    expect({outcome, logged: errors.length}).toEqual({outcome: 'hi', logged: 1});
  });

  it('logs nothing for a store that implements no save', async () => {
    const outcome = await turn(new InMemorySessionStore());

    expect({outcome, logged: errors.length}).toEqual({outcome: 'hi', logged: 0});
  });

  it('saves even when an afterSession hook throws', async () => {
    const saved: string[] = [];
    const store = recordingSessionStore(session => void saved.push(session.sessionId));
    const hooks = {
      afterSession: () => {
        throw new Error('hook exploded');
      },
    };
    const orchestrator = createChatOrchestrator(answering('hi'), writeSignalPromptBuilder, undefined, {
      sessionStore: store,
      hooks: hooks as never,
    });

    const outcome = await orchestrator
      .processMessage(sessionWith('hello'))
      .catch((error: Error) => `threw: ${error.message}`);

    expect({outcome, saved}).toEqual({outcome: 'threw: hook exploded', saved: ['s1']});
  });
});
